using System;using System.Collections.Generic;using WildsEngine.Discoveries.Abstractions.Clusters;using WildsEngine.Discoveries.Abstractions.Narratives;using WildsEngine.Discoveries.Base;
namespace WildsEngine.Discoveries.Policies { public sealed class RecognitionCentroidDistanceNarrativeMetric:IdentifierBase,IDiscoveryNarrativeMetric { public RecognitionCentroidDistanceNarrativeMetric(string slug="recognition-centroid-distance"):base(Guid.NewGuid(),slug){}public double Measure(IDiscoveryClusterRecognitionResult left,IDiscoveryClusterRecognitionResult right){if(left==null||right==null)throw new ArgumentNullException();double sum=0;foreach(var p in left.Mapping.Centroid){if(!right.Mapping.Centroid.TryGetValue(p.Key,out var r))throw new InvalidOperationException("Narrative mappings must share dimensions.");var d=p.Value-r;sum+=d*d;}return Math.Sqrt(sum);} } }
